import {renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import {osmosisCases,osmosisState,osmosisRows,percentageChange,massRate,mean,plotValid,practicalPlanValid}from './osmosis-models.js?v=20261023-physicscomplete01';
import {osmosisFigure,osmosisGraph,osmosisBench}from './osmosis-figures.js?v=20261023-physicscomplete01';
const opts=(items,v)=>'<option value="">Choose…</option>'+items.map(([k,t])=>`<option value="${k}"${String(v)===k?' selected':''}>${t}</option>`).join('');
export function showOsmosis(id='dilute',w={}){const c=osmosisCases.find(c=>c.id===id)||osmosisCases[0],f=osmosisState(c.id,w.step);renderCustomModel({name:c.name,formula:f.step?c.effect:'Predict water movement',kicker:'CUTAWAY PLANT CELL · SYMBOLIC VOLUME',atoms:[],bonds:[],radius:3,viewKey:'osmosis-cell',startPaused:true,note:'Water only crosses · wall fixed · no rate scale',aria:c.description+' '+(f.step?c.effect:'Initial state')+'. Fixed cell wall and changing cell contents. Arrows in the2D view represent water in both directions.',diagram:osmosisFigure(c.id,f.step)+'<p class="diagram-caption">A partially permeable membrane admits water, not the model solute. Squares show relative outside solute, not water count. Fixed reservoir conditions and exaggerated cell changes; not a measured rate or full pressure model.</p>',build:(g,T)=>{const wall=new T.Mesh(new T.BoxGeometry(2.5,3.1,1.6),new T.MeshStandardMaterial({color:0xd4dfe7,transparent:true,opacity:.12,roughness:.3,depthWrite:false}));g.add(wall);g.add(new T.LineSegments(new T.EdgesGeometry(wall.geometry),new T.LineBasicMaterial({color:0xd4dfe7})));const membrane=new T.Mesh(new T.BoxGeometry(1.95*f.scale,2.4*f.scale,1.1*f.scale),new T.MeshStandardMaterial({color:0xed8b78,transparent:true,opacity:.25,depthWrite:false,roughness:.25}));g.add(membrane);const vac=new T.Mesh(new T.BoxGeometry(1.55*f.scale,1.85*f.scale,.85*f.scale),new T.MeshStandardMaterial({color:0x91a5b3,roughness:.3}));vac.position.y=.03;g.add(vac);const nucleus=new T.Mesh(new T.SphereGeometry(.17,24,16),new T.MeshStandardMaterial({color:0xed8b78,roughness:.25}));nucleus.position.set(-.7*f.scale,-.8*f.scale,.5*f.scale);g.add(nucleus);}});}
const dataTable=()=>'<div class="osmo-table-wrap"><table class="osmo-table"><caption>Original illustrative results ·2 hours · initial mass2.00 g each</caption><thead><tr><th>mol dm⁻³</th><th>Final1/g</th><th>Final2/g</th><th>Final3/g</th></tr></thead><tbody>'+osmosisRows.map(r=>'<tr><th>'+r.concentration+'</th>'+r.finals.map(v=>'<td>'+v.toFixed(2)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
export function showOsmosisPractical(kind='method',w={}){const points=Object.entries(w.points||{}).filter(([i,y])=>String(y).trim()!==''&&Number.isFinite(Number(y))).map(([i,y])=>[osmosisRows[Number(i)].concentration,Number(y)]);renderDiagram(kind==='graph'?'Build the results graph':'Plant-tissue investigation',kind==='graph'?'Plot mean percentage mass change':'Same starting conditions · varying sucrose concentration',kind==='graph'?osmosisGraph({points})+'<p class="diagram-caption">Points come from your entries. Joined points guide interpretation; they do not establish a precise biological law. Original illustrative data, not measurements from a real class experiment.</p>':osmosisBench(w.ran)+'<p class="diagram-caption">Equal-sized tissue pieces and labelled solutions are schematic. The simulation does not establish weighing, cutting or experimental competence.</p>','PREPARE, MEASURE & INTERPRET');}
export function mountOsmosis(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s),practical=l.widget==='osmosis-practical',total=practical?4:3;w.task??=0;w.passed??=[];const task=w.task%total,tail='<button class="secondary" id="checkOsmosis">Check reasoning</button><button class="secondary" id="nextOsmosis">Next challenge →</button><p id="osmosisProgress">'+w.passed.length+' / '+total+' complete</p>';const complete=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#osmosisProgress').textContent=w.passed.length+' / '+total+' complete';};
if(!practical){const c=osmosisCases[task];w.cells??={};const r=w.cells[c.id]??={step:0};root.innerHTML=`<p><b>${task+1} / 3 · ${c.name}</b></p><p>${c.description} The model solute cannot cross the membrane; water can.</p><label class="field-label" for="waterPrediction">Predict net water movement</label><select id="waterPrediction" class="lab-select">${opts([['in','Into the cell'],['out','Out of the cell'],['balanced','No net movement']],r.answer)}</select><button class="secondary" id="stepWater">Step water exchange →</button><label class="field-label" for="waterExplanation">What crosses the model membrane?</label><select id="waterExplanation" class="lab-select">${opts([['water','Water; solute stays on its side'],['solute','Only solute'],['none','Nothing can ever pass']],r.explanation)}</select><p id="waterReadout" aria-live="polite"></p>`+tail;const draw=()=>{const f=osmosisState(c.id,r.step);showOsmosis(c.id,r);$('#waterReadout').textContent='Step '+f.step+' · water in '+f.inward+', water out '+f.outward+'. '+(f.step?c.effect:'Prediction first.')+(c.id==='equal'&&f.step?' Water continues moving both ways.':'');};$('#waterPrediction').onchange=e=>{r.answer=e.target.value;save();};$('#waterExplanation').onchange=e=>{r.explanation=e.target.value;save();};$('#stepWater').onclick=()=>{if(!r.answer){feedback('Predict before running water exchange.',true);return;}r.step=Math.min(4,r.step+1);save();draw();};$('#checkOsmosis').onclick=()=>{if(r.step<4){feedback('Step through all4 snapshots to compare the cell contents with the fixed wall.',true);return;}if(r.answer!==c.answer||r.explanation!=='water'){feedback('Water moves overall from the more dilute solution to the more concentrated through a partially permeable membrane. At equal effective concentrations, water still moves both ways with no net movement.',true);return;}feedback(c.effect+'. Osmosis concerns water; diffusion of solute is a different process.');complete();};draw();
}else if(task===0){root.innerHTML=`<p><b>1 / 4 · Plan a fair investigation</b></p><p>Use a range of sucrose concentrations. Predict the change in the most dilute solution, then choose controls and a weighing method. In a real laboratory, cutting needs teacher supervision.</p><label class="field-label" for="practicalPrediction">Most dilute solution: tissue mass will…</label><select id="practicalPrediction" class="lab-select">${opts([['gain','Increase overall'],['loss','Decrease overall'],['same','Always remain identical']],w.prediction)}</select><label class="field-label" for="practicalControl">Keep constant</label><select id="practicalControl" class="lab-select">${opts([['same','Dimensions, time, temperature'],['different','Change time for each solution'],['concentration','Keep concentration identical']],w.control)}</select><label class="field-label" for="practicalBlot">Before final weighing</label><select id="practicalBlot" class="lab-select">${opts([['wet','Weigh with liquid dripping'],['blot','Blot gently and consistently'],['squeeze','Squeeze out internal water']],w.blot)}</select><button class="secondary" id="runOsmosisPractical">Run illustrative investigation</button><div id="osmoResults">${w.ran?dataTable():''}</div>`+tail;for(const [id,key]of[['practicalPrediction','prediction'],['practicalControl','control'],['practicalBlot','blot']])$('#'+id).onchange=e=>{w[key]=e.target.value;save();};$('#runOsmosisPractical').onclick=()=>{if(!practicalPlanValid(w)){feedback('Vary only solution concentration. Match tissue dimensions, time and temperature, blot consistently, and use the water gradient to predict the dilute solution result.',true);return;}w.ran=true;save();$('#osmoResults').innerHTML=dataTable();showOsmosisPractical('data',w);feedback('Three repeats per concentration help identify variation. These supplied results are illustrative.');};$('#checkOsmosis').onclick=()=>{if(!w.ran||!practicalPlanValid(w)){feedback('Complete the fair-test choices and run the model first.',true);return;}feedback('A concentration range, matched conditions, initial/final measurements, consistent blotting and repeats support a valid comparison.');complete();};showOsmosisPractical('method',w);
}else if(task===1){root.innerHTML='<p><b>2 / 4 · Calculate a loss and a rate</b></p>'+dataTable()+`<p>Use0.6 mol dm⁻³. Find the mean final mass, signed percentage mass change and signed mean mass-change rate over2 hours. Negative values show loss.</p>${[['meanFinal','Mean final mass / g'],['percent','Percentage mass change / %'],['rate','Mean mass-change rate / g h⁻¹']].map(([key,label])=>`<label class="field-label" for="osmo-${key}">${label}</label><input id="osmo-${key}" class="lab-input" type="number" step="any" value="${w[key]??''}">`).join('')}`+tail;for(const key of['meanFinal','percent','rate'])$('#osmo-'+key).oninput=e=>{w[key]=e.target.value;save();};$('#checkOsmosis').onclick=()=>{if(!w.ran){feedback('Run the planned investigation first.',true);return;}const r=osmosisRows[3],answers={meanFinal:mean(r.finals),percent:percentageChange(2,r.mean),rate:massRate(2,r.mean,2)};if(Object.entries(answers).some(([k,v])=>String(w[k]??'').trim()===''||Math.abs(Number(w[k])-v)>.005)){feedback('Mean = sum ÷3. Percentage change = (final−initial) ÷ initial ×100. Divide signed mass change by2 hours for g h⁻¹; use the initial mass in the percentage denominator.',true);return;}feedback('Mean1.88 g; change−6%; mean signed rate−0.06 g h⁻¹. The negative sign records water loss overall.');complete();};showOsmosisPractical('data',w);
}else if(task===2){w.points??={};w.plotRow??='0';root.innerHTML='<p><b>3 / 4 · Plot the concentration series</b></p>'+dataTable()+`<p>For each concentration, calculate mean percentage mass change from the initial2.00 g. Plot all five points. The horizontal axis is concentration; vertical is percentage change.</p><label class="field-label" for="osmoPlotRow">Concentration / mol dm⁻³</label><select id="osmoPlotRow" class="lab-select">${opts(osmosisRows.map((r,i)=>[String(i),String(r.concentration)]),w.plotRow)}</select><label class="field-label" for="osmoPlotValue">Mean percentage change / %</label><input id="osmoPlotValue" class="lab-input" type="number" step="any" value="${w.plotDraft??''}"><button class="secondary" id="plotOsmosisPoint">Plot or replace point</button><p id="plotReadout" aria-live="polite"></p>`+tail;const draw=()=>{showOsmosisPractical('graph',w);$('#plotReadout').textContent='Plotted: '+Object.entries(w.points).map(([i,y])=>osmosisRows[Number(i)].concentration+': '+y+'%').join('; ');};$('#osmoPlotRow').onchange=e=>{w.plotRow=e.target.value;save();};$('#osmoPlotValue').oninput=e=>{w.plotDraft=e.target.value;save();};$('#plotOsmosisPoint').onclick=()=>{if(String(w.plotDraft??'').trim()===''||!Number.isFinite(Number(w.plotDraft))||!osmosisRows[Number(w.plotRow)]){feedback('Choose a concentration and enter a signed percentage.',true);return;}w.points[w.plotRow]=Number(w.plotDraft);save();draw();};$('#checkOsmosis').onclick=()=>{if(!plotValid(w.points)){feedback('Check all five calculated percentages and their concentration coordinates. A mass loss belongs below zero; an unplotted point is not a zero reading.',true);return;}feedback('The points decrease from+12% to−12%. Zero mass change lies at0.4 mol dm⁻³ in these supplied results.');complete();};draw();
}else{root.innerHTML=`<p><b>4 / 4 · Interpret the result</b></p><label class="field-label" for="osmoZero">Estimated concentration for no net mass change / mol dm⁻³</label><input id="osmoZero" class="lab-input" type="number" step="any" value="${w.zero??''}"><label class="field-label" for="osmoZeroMeaning">At zero mass change…</label><select id="osmoZeroMeaning" class="lab-select">${opts([['balanced','Water moves both ways, balanced'],['stopped','All water movement stops'],['solute','No membrane exists']],w.zeroMeaning)}</select><label class="field-label" for="osmoImprove">Improve an uncertain zero-crossing estimate</label><select id="osmoImprove" class="lab-select">${opts([['repeat','Repeats; closer spacing'],['delete','Remove results without a reason'],['guarantee','One point proves the exact tissue value']],w.improve)}</select>`+tail;$('#osmoZero').oninput=e=>{w.zero=e.target.value;save();};$('#osmoZeroMeaning').onchange=e=>{w.zeroMeaning=e.target.value;save();};$('#osmoImprove').onchange=e=>{w.improve=e.target.value;save();};$('#checkOsmosis').onclick=()=>{if(String(w.zero??'').trim()===''||Math.abs(Number(w.zero)-.4)>.005||w.zeroMeaning!=='balanced'||w.improve!=='repeat'){feedback('Find where the graph crosses0% mass change. This estimates balance, not stopped water motion or a universal exact concentration. Repeats and closer-spaced concentrations strengthen the estimate.',true);return;}feedback('For these data,0.4 mol dm⁻³ estimates no net mass change. Tissue variability and measurement uncertainty remain.');complete();};showOsmosisPractical('graph',w);}
$('#nextOsmosis').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge before continuing.',true);return;}w.task=(task+1)%total;save();feedback('');mountOsmosis(l,p,root,{save,done,feedback});};}
